-- The code fixture's reader has a separate login so its tests never change another suite's
-- password. $(PASSWORD) is generated by tests/sqlserver_code.rs for this run.
USE master;
GO
IF SUSER_ID(N'schemacraft_code_reader') IS NULL
    CREATE LOGIN schemacraft_code_reader WITH PASSWORD = N'$(PASSWORD)', CHECK_POLICY = OFF;
ELSE
    ALTER LOGIN schemacraft_code_reader WITH PASSWORD = N'$(PASSWORD)', CHECK_POLICY = OFF;
GO
USE SchemaCraftCode;
GO
CREATE USER schemacraft_code_reader FOR LOGIN schemacraft_code_reader;
ALTER ROLE db_datareader ADD MEMBER schemacraft_code_reader;
GO
